// Settle applies the mechanism to a delivery whose handler failed
// transiently, and is the only disposition call such a handler makes. It
// picks exactly one of:
//
//   - the circuit breaker — the consumer's ack floor has been stalled past
//     FloorAge and this message has itself been failing that long (see
//     shouldQuarantine): capture to the DLQ and Ack, well before the ladder
//     would have run out (Cause
//     CauseFloorAge). Under [BreakerObserve] the condition is reported on
//     the Settlement and the message stays on the ladder;
//   - exhaustion — the ladder is spent (delivery MaxDeliver-CaptureReserve or
//     later): capture to the DLQ and Ack (Cause CauseExhausted);
//   - the ladder — leave the delivery untouched so the server redelivers it
//     (Outcome OutcomeRetried).
//
// reason is recorded on the captured copy's Nats-Dlq-Reason header, prefixed
// with the cause, so the DLQ says why a message is there and not just that it
// is.
//
// # When the capture itself fails
//
// A capture failure is never allowed to become a drop, and the Settlement
// says which of two very different things happened:
//
//   - Deliveries remain (CaptureReserve is doing its job): the original is
//     left for the server to redeliver, the error returned is
//     settle:dlq_publish_failed, and the
//     Settlement reports OutcomeRetried with the Cause of the terminal branch
//     that could not complete — so the caller's metrics show a DLQ path being
//     reached and failing rather than one sitting idle. The next delivery
//     retries the capture.
//   - No deliveries remain: the delivery cap is reached, so nothing
//     will retry. The Settlement reports [OutcomeStranded] and the message is
//     left unsettled, pinning the ack floor so the monitor fires — ENT-1492's
//     deliberate posture for a degraded DLQ path, and the one state this
//     package cannot resolve on its own. It is reported as what it is rather
//     than dressed up as a retry.
//
// An Ack that fails after a successful capture leaves the original to
// redeliver and be captured again; a duplicate in the DLQ beats a lost
// message, and the Settlement reports OutcomeRetried. Strictly that outcome is
// also unconfirmed — the ack may have landed, in which case no redelivery
// comes — but both branches are benign and neither wants an operator, so it is
// not worth a third state. On the FINAL delivery it is worth one, because
// there the difference decides whether a human should act:
// [OutcomeUncertain].
func (r *Retry) Settle(ctx context.Context, msg jetstream.Msg, reason string) (Settlement, error) {
	delivered := backoff.NumDelivered(msg)
	now := r.clock()
	// With no stall signal there is no breaker, so none of its bookkeeping
	// runs: no failure clocks, no map, no quarantine budget. A consumer on
	// the bounded-ladder configuration pays nothing for a mechanism it has
	// not opted into.
	var failingFor time.Duration
	if r.monitor != nil {
		failingFor = r.noteFailure(streamSeq(msg), now)
	}
	quarantine, floor, age := r.shouldQuarantine(msg, delivered, failingFor, now)

	s := Settlement{
		Delivered:      delivered,
		Floor:          floor,
		FloorAge:       age,
		FailingFor:     failingFor,
		BreakerTripped: quarantine,
	}
	// Report an observed trip wherever it happens, not only where it changes
	// the outcome. A trip that coincides with exhaustion still counts toward
	// what enforcing would have done, and logging it only on the ladder
	// branch would leave log-based counting quietly short of the metric.
	if quarantine && r.cfg.Breaker != BreakerEnforce {
		logger, name := r.log()
		logger.WarnContext(ctx, name+": breaker would dead-letter this message (observe only)",
			slog.String("reason", reason),
			slog.Int("delivered", delivered),
			slog.Duration("failing_for", s.FailingFor),
			slog.Uint64("ack_floor", floor),
			slog.Duration("floor_stalled_for", age))
	}
	switch {
	case quarantine && r.cfg.Breaker == BreakerEnforce:
		s.Cause = CauseFloorAge
	case r.ladderSpent(delivered):
		s.Cause = CauseExhausted
	default:
		return r.awaitRedelivery(ctx, msg, s), nil
	}
	// A terminal branch reached on a done context is a shutdown landing on
	// this delivery, not evidence about the message (COR-2224). While the
	// broker still has deliveries to serve, leave it on the ladder — the
	// CaptureReserve deliveries exist for exactly this kind of retry. At the
	// broker's own cap nothing redelivers, so the non-lossy capture below
	// runs anyway (it is detached from the cancellation, see terminate):
	// a replayable DLQ copy beats a message stranded on purpose.
	if ctx.Err() != nil && !r.brokerCapReached(delivered) {
		logger, name := r.log()
		logger.InfoContext(ctx, name+": settlement deferred; context done on a terminal delivery, leaving it for redelivery",
			slog.String("would_be_cause", string(s.Cause)),
			slog.String("reason", reason),
			slog.Int("delivered", delivered))
		s.Cause = CauseShutdown
		return r.awaitRedelivery(ctx, msg, s), nil
	}
	return r.terminate(ctx, msg, s, reason)
}

// brokerCapReached reports whether the broker will serve no further delivery
// of this message: NumDelivered has reached the consumer's MaxDeliver. Missing
// metadata (0) reads as deliveries remaining, the same safe default as
// ladderSpent and backoff.IsFinalDelivery.
func (r *Retry) brokerCapReached(delivered int) bool {
	return delivered > 0 && delivered >= r.cfg.MaxDeliver
}

// terminate runs the capture-then-settle sequence shared by [Settle]'s two
// terminal branches and [Retry.DeadLetter], and classifies every way it can
// fall short. s must already carry its Cause.
func (r *Retry) terminate(ctx context.Context, msg jetstream.Msg, s Settlement, reason string) (Settlement, error) {
	logger, name := r.log()
	spent := r.brokerCapReached(s.Delivered)

	// Capture and settle on a context that shutdown cannot cancel. The module's
	// shutdown ordering cancels the loops' context, joins them, and only THEN
	// drains the connections (nuts.ShutdownGroup, COR-923) — so throughout the
	// join window this ctx is already done while the connection is still fully
	// usable. On the handler ctx a rollout landing on the FINAL delivery fails
	// the capture on ctx.Err() alone and reports OutcomeStranded: a strand
	// manufactured by timing, on a message that was perfectly capturable with
	// the broker right there. The same cancellation on the DoubleAck would
	// report OutcomeUncertain and point a responder at a message that only
	// needed one more round-trip.
	//
	// Detaching cancellation cannot hang the drain, because neither operation
	// was relying on ctx for its bound: the capture publish and the DoubleAck
	// each apply their own (dlqPublishTimeout, dlqAckTimeout). WithoutCancel
	// drops the parent's deadline along with its cancellation, which is why
	// those explicit bounds are what matters. This narrows the window rather
	// than closing it absolutely — a terminate outlasting nuts.DefaultJoinTimeout
	// still has the connection drained under it — but it removes the case that
	// failed immediately and by construction.
	//
	// Values are preserved, so the span and trace context the handler was given
	// still carry into the capture.
	//
	// The WHOLE settle sequence runs detached, not just the capture:
	// natsmsg.DeadLetter detaches its own publish too (COR-1487), but this is what
	// covers the DoubleAck below, which nothing else does.
	settleCtx := context.WithoutCancel(ctx)

	if err := r.capture(settleCtx, msg, s.Cause, reason); err != nil {
		if spent {
			// Out of deliveries: no redelivery follows, so saying "retried"
			// would be a lie. Leave it unsettled and name the state.
			s.Outcome = OutcomeStranded
			logger.ErrorContext(ctx, name+": message stranded; dead-letter capture failed with no deliveries left",
				slog.Any("error", err),
				slog.String("cause", string(s.Cause)),
				slog.String("reason", reason),
				slog.Int("delivered", s.Delivered),
				slog.Uint64("ack_floor", s.Floor))
			r.observe(ctx, msg, s)
			return s, fmt.Errorf("settle:stranded: %w", err)
		}
		// Deliveries remain — leave it to the ladder so the capture is retried
		// on the next delivery. Preserve the cause: the terminal branch was
		// reached and could not complete.
		waiting := r.awaitRedelivery(ctx, msg, s)
		waiting.Cause = s.Cause
		return waiting, err
	}
	s.Captured = true

	// DoubleAck, not Ack: a plain Ack is fire-and-forget, so a lost one leaves
	// the floor pinned with nothing reporting it. Waiting for the server's
	// confirmation is what makes the settlement a fact rather than a hope, and
	// it costs one round-trip on a path that only runs when a message is being
	// given up on.
	ackCtx, cancel := context.WithTimeout(settleCtx, dlqAckTimeout)
	defer cancel()
	if err := msg.DoubleAck(ackCtx); err != nil {
		if spent {
			// The copy is safe in the DLQ; whether the ORIGINAL settled is
			// unknown. A failed DoubleAck means the confirmation did not come
			// back, which is not the same as the ack not landing — so this is
			// reported as uncertain rather than stranded, and the log says
			// what to check. See [OutcomeUncertain] for why over-claiming
			// here is worse than useless: it points a responder at a
			// destructive remedy for a message that may already be settled.
			s.Outcome = OutcomeUncertain
			logger.ErrorContext(ctx, name+": settlement unconfirmed; captured to the DLQ but the ack was not acknowledged, with no deliveries left",
				slog.Any("error", err),
				slog.String("cause", string(s.Cause)),
				slog.Int("delivered", s.Delivered),
				slog.Uint64("ack_floor", s.Floor),
				slog.String("check", "has the ack floor advanced past this message? if so the ack landed and no action is needed. if not, that is NOT proof it is unsettled — an older unacked message pins the floor regardless; the copy is already safe in the DLQ, so do not remove the original until the floor is shown to be pinned AT this sequence"))
			r.observe(ctx, msg, s)
			return s, fmt.Errorf("settle:dlq_ack_unconfirmed: %w", err)
		}
		// A delivery remains: the message redelivers and is captured again.
		// A duplicate in the DLQ beats a pinned floor.
		s.Outcome = OutcomeRetried
		r.observe(ctx, msg, s)
		return s, fmt.Errorf("settle:dlq_ack_failed: %w", err)
	}

	s.Outcome = OutcomeDeadLettered
	r.forgetFailure(streamSeq(msg))
	logger.WarnContext(ctx, name+": dead-lettered",
		slog.String("cause", string(s.Cause)),
		slog.String("reason", reason),
		slog.Int("delivered", s.Delivered),
		slog.Duration("failing_for", s.FailingFor),
		slog.Uint64("ack_floor", s.Floor),
		slog.Duration("floor_stalled_for", s.FloorAge))
	r.observe(ctx, msg, s)
	return s, nil
}

// DeadLetter captures msg to the DLQ and Acks it immediately, for a failure
// the handler knows no redelivery can fix — an unprocessable payload, a
// reference that will never resolve. It is the non-lossy replacement for a
// bare Term: the same terminal effect on the consumer, but the raw message and
// its headers survive in the DLQ.
//
// The objection to Term is the missing record, not the settlement. Measured
// against nats-server 2.14.3 single-node, Term settles cleanly on limits,
// workqueue and interest retention alike — the ack floor advances past it and
// NumAckPending returns to zero — so "Term leaves the message unsettled" is
// not a belief this package should carry, whatever ENT-1492's write-up
// implies. What Term does not do is leave any trace of what was discarded,
// and that is the whole reason for capturing first.
//
// As in [Settle], a capture failure leaves the message for the server to
// redeliver rather than dropping it, and returns the error.
//
// This is also the seam for an adopter that wants the stall signal without
// the library's automatic disposition: build a [FloorMonitor], leave
// RetryConfig.Monitor nil, and call DeadLetter from your own quarantine rule.
func (r *Retry) DeadLetter(ctx context.Context, msg jetstream.Msg, reason string) (Settlement, error) {
	var floor uint64
	var age, failingFor time.Duration
	if r.monitor != nil {
		floor, age, _ = r.monitor.FloorStall()
		failingFor = r.noteFailure(streamSeq(msg), r.clock())
	}
	delivered := backoff.NumDelivered(msg)
	return r.terminate(ctx, msg, Settlement{
		Cause:      CausePermanent,
		Delivered:  delivered,
		FailingFor: failingFor,
		Floor:      floor,
		FloorAge:   age,
	}, reason)
}

// streamSeq is the message's stream sequence, or 0 when metadata is
// unavailable (a synthetic message). All such messages share the zero key,
// which is harmless: they cannot satisfy the breaker's above-the-floor
// condition anyway.
func streamSeq(msg jetstream.Msg) uint64 {
	if meta, err := msg.Metadata(); err == nil && meta != nil {
		return meta.Sequence.Stream
	}
	return 0
}

// capture republishes the raw message and headers to the DLQ subject, tagging
// the reason with its cause.
func (r *Retry) capture(ctx context.Context, msg jetstream.Msg, cause Cause, reason string) error {
	if err := natsmsg.DeadLetter(ctx, r.cfg.Publisher, r.cfg.DLQSubject, msg, string(cause)+": "+reason); err != nil {
		logger, name := r.log()
		logger.ErrorContext(ctx, name+": settle:dlq_publish_failed",
			slog.Any("error", err),
			slog.String("dlq_subject", r.cfg.DLQSubject),
			slog.String("cause", string(cause)))
		return fmt.Errorf("settle:dlq_publish_failed: %w", err)
	}
	return nil
}

// awaitRedelivery leaves the delivery UNTOUCHED so the server's ladder brings
// it back, and completes s.
//
// Not acking is the disposition here, and it is deliberate rather than an
// omission. A consumer's BackOff ladder governs acknowledgement TIMEOUTS: let
// AckWait expire and the server redelivers on the configured rung. A plain
// Nak does the opposite — it asks for immediate redelivery and the ladder is
// never consulted, so a transient failure hot-loops through MaxDeliver and
// reaches the DLQ in milliseconds. Measured against a live server with a
// 3s/3s/3s ladder: Nak() redelivers in 0s, no-ack in 3s.
//
// NakWithDelay does not rescue it either, and the reason is stronger than
// "the client would have to know the delay". The server does not honour the
// requested delay as given: processNak backdates the pending timestamp by
// AckWait, and checkPending then measures it against the CURRENT rung, so the
// effective wait is d + (BackOff[rung] - BackOff[0]). Measured on a
// [200ms, 1200ms] ladder, NakWithDelay(50ms) redelivered at 50ms, then
// 1050ms, then 1050ms. On a growing ladder a client simply cannot express its
// own envelope — which is also the likeliest explanation for ENT-1535's
// unverified "~78s apart against a 5m first rung" observation.
//
// So doing nothing is not merely the tidiest way to defer to the one ladder;
// it is the only disposition whose timing is predictable.
//
// The cost is that the delivery stays ack-pending for the whole rung, so a
// consumer with a long ladder and many concurrent failures needs MaxAckPending
// sized for it. That is inherent to a server-side ladder, not to this choice.
func (r *Retry) awaitRedelivery(ctx context.Context, msg jetstream.Msg, s Settlement) Settlement {
	s.Outcome = OutcomeRetried
	r.observe(ctx, msg, s)
	return s
}

func (r *Retry) observe(ctx context.Context, msg jetstream.Msg, s Settlement) {
	if r.cfg.OnSettle != nil {
		r.cfg.OnSettle(ctx, msg, s)
	}
}

