// natsDrainBackstop bounds how long each NATS connection's graceful drain blocks
// at shutdown waiting to flush and reach CLOSED. nuts.Drain caps the
// subscription-drain phase at nuts.DefaultDrainTimeout (5s); nats.go then runs an
// unconditional ~5s publish flush before CLOSED, so this total-time-to-CLOSED
// backstop must exceed those combined or it would fire mid-flush — 12s leaves
// slack. Real drains complete in milliseconds once the consumer loops have joined
// (COR-923 serve ordering); this ceiling only bites if the NATS server is
// unreachable, where the pod grace period / kubelet SIGKILL is the last backstop.
const natsDrainBackstop = 12 * time.Second

// drainNATS adapts the error-returning go-nuts v0.7 drain contract to the
// dependency cleanup callbacks in this package, whose established shape is
// func(). Command-level drains join the error into their return value instead.
func drainNATS(ctx context.Context, nc *nats.Conn, name string) {
	if err := nuts.Drain(ctx, nc, name, nil, natsDrainBackstop); err != nil {
		slogutil.Error(ctx, "NATS drain failed", slog.String("connection", name), slog.Any("error", err))
	}
}

// globalModeSubsystems is THE manifest of the background units global mode
// runs, in Serve() start order (COR-832): rate-limit cleanup first, the
// globaldb region check, then the perms webhook + read-model consumers when
// NATS built them.
//
// Global deliberately does NOT run:
//   - the provisioning reconciler — global has no regional store to drive, and
//     COR-730 wired resourceSvc into global; the old resourceSvc-only gate
//     started the reconciler here and crashlooped entire-core-global. Its
//     absence from this manifest is now the structural guard (there is no path
//     that can add it), superseding the former data-gate.
//   - mirror-done / perms-backfill consumers — global's mirrorRepoSvc is
//     read-only, so there is no writable placement store for them to reconcile.
//   - the verified-email consumer — verified_emails is home-jurisdiction
//     partitioned data (COR-661/COR-757), owned by regional mode only.
